int liczbaSpojnychSkladowych(Map<Integer, List<Integer>> graf, int liczbaWezlow) {
    Set<Integer> odwiedzone = new HashSet<>();
    int liczbaSkladowych = 0;
    for (int wezel = 0; wezel < liczbaWezlow; wezel++) {
        if (!odwiedzone.contains(wezel)) {
            liczbaSkladowych++; // nowy, nieodwiedzony wezel = nowa spojna skladowa
            dfs(graf, wezel, odwiedzone, new ArrayList<>()); // 'zatop' cala skladowa naraz
        }
    }
    return liczbaSkladowych;
}

