int najwiekszaWyspa(int[][] s) {
    int max = 0;
    for (int i = 0; i < s.length; i++)
        for (int j = 0; j < s[0].length; j++)
            max = Math.max(max, dfs(s, i, j));
    return max;
}

int dfs(int[][] s, int w, int k) {
    if (w < 0 || k < 0 || w >= s.length || k >= s[0].length || s[w][k] == 0) return 0;
    s[w][k] = 0; // oznacz jako odwiedzone PRZED zejściem w głąb
    return 1 + dfs(s, w + 1, k) + dfs(s, w - 1, k) + dfs(s, w, k + 1) + dfs(s, w, k - 1);
}
// Uwaga: metoda niszczy siatkę wejściową - jeśli to niedopuszczalne, użyj osobnej tablicy boolean[][].

