void zatop(int[][] s, int w, int k) {
    if (s[w][k] == 0 || w < 0 || k < 0 || w >= s.length || k >= s[0].length) return;
    s[w][k] = 0;
    zatop(s, w + 1, k);
    zatop(s, w - 1, k);
    zatop(s, w, k + 1);
    zatop(s, w, k - 1);
}

